async function createInvite() { const epoch = state.epoch; const userId = state.user?.id; try { const x = await req(`/groups/${state.selected}/invite`, { method: 'POST', body: {} }); if (epoch !== state.epoch || userId !== state.user?.id) return; state.invite = `${location.origin}/daily.html#invite=${encodeURIComponent(x.token)}`; render(); } catch (x) { if (epoch === state.epoch) fail(x); } }
